/** Returns true if this is an output parameter with the AutoSizeResult modifier. */
internal val isAutoSizeResultOut
    get() = has<AutoSizeResultParam>() && !isInput

internal fun isArrayParameter(autoSizeResultOutParams: Int) = nativeType.isArray && (!isAutoSizeResultOut || autoSizeResultOutParams != 1)

internal fun toNativeType(binding: APIBinding?, pointerMode: Boolean = false) =
    if (binding == null || this === JNI_ENV || nativeType is StructType)
        nativeType.name.let {
            if (pointerMode && nativeType is StructType) "$it *" else it
        }
    else if (nativeType.mapping === PrimitiveMapping.POINTER || nativeType is PointerType<*>)
        "intptr_t"
    else
        nativeType.jniFunctionType

override fun validate(modifier: ParameterModifier) = modifier.validate(this)

internal fun copy(nativeType: NativeType = this.nativeType) = Parameter(
    nativeType,
    name,
    documentation
).copyModifiers(this)

private fun copyModifiers(other: Parameter): Parameter {
    if (other.hasModifiers())
        this._modifiers = HashMap(other.modifiers)
    return this
}

internal fun removeArrayModifiers(): Parameter {
    if (has(optional) && has<MultiType>())
        _modifiers.remove(Nullable::class)

    _modifiers.remove(PointerArray::class)
    _modifiers.remove(Return::class)
    _modifiers.remove(SingleValue::class)
    _modifiers.remove(MultiType::class)

    return this
}

private fun PrintWriter.generateNativeMethod(constantMacro: Boolean, nativeOnly: Boolean, hasReuse: Boolean) {
    println()

    printUnsafeJavadoc(constantMacro, nativeOnly)

    if (returns.nativeType is JObjectType && returnsNull) {
        println("$t@Nullable")
    }

    val retType = returns.nativeMethodType

    if (nativeOnly) {
        val retTypeAnnotation = returns.nativeType.annotation(retType)
        if (retTypeAnnotation != null)
            println("$t$retTypeAnnotation")
    }

    print("$t${if (constantMacro) "private " else accessModifier}static${if (hasReuse) "" else " native"} $retType ")
    if (!nativeOnly) print('n')
    print(name)
    print("(")

    val nativeParams = getNativeParams()
    printList(nativeParams) {
        it.asNativeMethodParam(nativeOnly)
    }
    if (hasFunctionAddressParam && !hasExplicitFunctionAddress) {
        if (nativeParams.any()) print(", ")
        print("long $FUNCTION_ADDRESS")
    }
    if (returns.isStructValue && !hasParam { it has ReturnParam }) {
        if (nativeClass.binding != null || nativeParams.any()) print(", ")
        print("long $RESULT")
    }

    if (hasReuse) {
        print(") {\n$t$t")
        if (retType != "void")
            print("return ")
        print("${get<Reuse>().source.className}.n$name(")
        printList(nativeParams) {
            it.name
        }
        if (hasFunctionAddressParam && !hasExplicitFunctionAddress) {
            if (nativeParams.any()) print(", ")
            print(FUNCTION_ADDRESS)
        }
        println(");\n$t}")
    } else {
        println(");")
    }
}

